//! 🧪️ Original native semantic authority and independent physical turn receipts.
use super::*;
use semio_os_store_snapshot_clone::{RetainedCloneEdit,RetainedCloneEditCursor,RetainedCloneEditStep,RetainedClonePreparationFactory};
use semio_os_store_one_item::{ArtifactStoreOneItemFootprint,ArtifactStoreOneItemGrant};
use semio_os_store_command::HistoryLane;
use semio_framework_value_snapshot_read::SnapshotReadRegistryHandle;
use super::super::ArtifactReplayPreparationFactory;
use semio_framework_value::retained_clone::{RetainedCloneBirthDemand,retained_clone_grant_admits};
#[derive(semio_framework_value::FactoryPayloadRetirement)]
struct ScalarEdit;
struct ScalarCursor{phase:u8,inverse:ManuallyDrop<Option<Vec<u64>>>,close:RetainedCloneClose,closing:bool,last_work:u64}
impl RetainedCloneEdit<u64,u64> for ScalarEdit{
 type Cursor=ScalarCursor;
 fn preflight(&self,value:&u64,_:HistoryLane)->Result<ArtifactStoreOneItemFootprint,&'static str>{if *value==0{return Err("scalar source must be positive")}Ok(ArtifactStoreOneItemFootprint{work_items:2,retained_bytes:4096})}
 fn begin_demand(&self)->RetainedCloneBirthDemand{RetainedCloneBirthDemand{capacity_bytes:0,depth:1}}
 fn snapshot_cursor_birth_demand(&self)->RetainedCloneBirthDemand{RetainedCloneBirthDemand{capacity_bytes:0,depth:1}}
 fn begin(&self,g:RetainedCloneGrant)->Result<(Self::Cursor,RetainedCloneProgress),ValueError>{let d=RetirementDemand{copy_bytes:size_of::<ScalarCursor>(),depth:1,..Default::default()};if !retained_clone_grant_admits(g,d){return Err(invalid("scalar edit cursor transfer not funded"));}Ok((ScalarCursor{phase:0,inverse:ManuallyDrop::new(None),close:Default::default(),closing:false,last_work:0},RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
}
impl RetainedCloneEditCursor<u64,u64> for ScalarCursor{
 fn next_work_demand(&self,_:RetainedCloneRef<'_,u64>,_:&u64,_:RetainedCloneRef<'_,u64>,_:usize)->Result<u64,ValueError>{Ok(1)}
 fn last_turn_work(&self)->u64{self.last_work}
 fn advance_demands(&self,_:RetainedCloneRef<'_,u64>,_:&u64,_:RetainedCloneRef<'_,u64>,_:usize)->Result<RetirementDemand,ValueError>{Ok(match self.phase{0=>RetirementDemand{copy_bytes:size_of::<Vec<u64>>()+size_of::<u64>(),capacity_bytes:size_of::<u64>(),depth:1,..Default::default()},1=>RetirementDemand{copy_bytes:size_of::<u64>()*2+size_of::<Vec<u64>>(),depth:1,..Default::default()},_=>Default::default()})}
 fn advance(&mut self,b:RetainedCloneRef<'_,u64>,post:&mut u64,m:RetainedCloneRef<'_,u64>,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneEditStep,ValueError>{self.last_work=0;let d=self.advance_demands(b,post,m,body)?;if self.closing||!retained_clone_grant_admits(g,d){return Ok(RetainedCloneEditStep::Progress(Default::default()));}if self.phase<2{self.last_work=1;}match self.phase{0=>{let mut rows=Vec::new();rows.try_reserve_exact(1).map_err(|_|invalid("scalar inverse allocation failed"))?;rows.push(*b.get());*self.inverse=Some(rows);self.phase=1;},1=>{*post=*m.get();self.phase=2;},_=>return Ok(RetainedCloneEditStep::Complete(Default::default()))}let p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()};Ok(if self.phase==2{RetainedCloneEditStep::Complete(p)}else{RetainedCloneEditStep::Progress(p)})}
 fn take_inverse(&mut self)->Option<Vec<u64>>{self.inverse.take()}
 fn foreign_step_presence(&self)->bool{false}
 fn cancel(&mut self){self.closing=true;}
 fn begin_close(&mut self)->bool{let first=!self.closing;self.closing=true;first}
 fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{self.last_work=0;if !self.close.is_empty(){let turn=self.close.step_granted(g);self.last_work=turn.work;return turn.result;}let turn=self.close.begin_granted(&mut self.inverse,g);self.last_work=turn.work;if let Some(step)=turn.result?{return Ok(step);}Ok(RetainedCloneStep::Complete(Default::default()))}
 fn next_close_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(self.close.next_owner_demands::<Vec<u64>>(self.inverse.is_some(),&None,4096)?.copy_bytes)}
 fn next_close_capacity_byte_demand(&self,b:usize)->Result<usize,ValueError>{Ok(self.close.next_owner_demands::<Vec<u64>>(self.inverse.is_some(),&None,b)?.capacity_bytes)}
 fn next_close_release_byte_demand(&self)->Result<usize,ValueError>{Ok(self.close.next_owner_demands::<Vec<u64>>(self.inverse.is_some(),&None,4096)?.release_bytes)}
 fn next_close_depth_demand(&self)->Result<usize,ValueError>{Ok(self.close.next_owner_demands::<Vec<u64>>(self.inverse.is_some(),&None,4096)?.depth)}
 fn terminal_is_empty(&self)->bool{self.closing&&self.inverse.is_none()&&self.close.is_empty()}
}
fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes<=4096&&d.capacity_bytes<=4096,"original semantic test grant {d:?}");RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
fn close_typed<T:RetireOwned>(value:T){let mut owner=semio_framework_value::retirement::controlled::ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();for _ in 0..10000{if owner.terminal_is_empty(){return;}let g=RetainedCloneGrant{maximum_copy_bytes:4096,..grant(owner.next_demand(4096).unwrap())};let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(g).unwrap());assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}panic!("typed semantic output {} did not close: {:?}",std::any::type_name::<T>(),owner.next_demand(4096));}
struct OriginalLawCaller{caller:semio_framework_job::OriginalJobFixtureCaller,decoder:semio_framework_job::OriginalJobDecodeOwner}
impl OriginalLawCaller{
 fn stock()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1<<24,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<30,maximum_release_bytes:1<<30,maximum_depth:128}}
 fn new()->Self{Self{caller:semio_framework_job::OriginalJobFixtureCaller::admit(semio_framework_job::OperationId(3671),semio_framework_job::Generation(7),Self::stock(),||Some(1),u64::MAX,1<<28),decoder:semio_framework_job::OriginalJobDecodeOwner::empty()}}
 fn native<R>(&mut self,g:RetainedCloneGrant,run:impl FnOnce(&mut semio_framework_value_native_owned::native_decoding::NativeDecodeControl<'_>)->(R,RetainedCloneProgress,u64))->R{
  self.native_work(g,1024,run)
 }
 fn native_work<R>(&mut self,g:RetainedCloneGrant,fuel:u64,run:impl FnOnce(&mut semio_framework_value_native_owned::native_decoding::NativeDecodeControl<'_>)->(R,RetainedCloneProgress,u64))->R{
  let mut output=None;self.caller.turn_with_decoder(g,&mut self.decoder,|cx|cx.with_original_work_loan(fuel,cx.deadline_us(),|cx|{let mut effects=RetainedCloneProgress::default();let mut work=0;let result=cx.with_native_receiving::<_,ValueError>(|control|{let admitted=control.owned_bytes();let((value,p,w),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||run(control));assert!(p.fits(g));assert_eq!(control.owned_bytes()-admitted,heap.requested_bytes);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));effects=p;work=w;output=Some(value);Ok(())});cx.consume_fuel(work);let posted=cx.consume_receiving_retained(g,effects);result?;posted?;Ok(())})).unwrap();output.unwrap()
 }
 fn close<T:RetireOwned>(&mut self,value:T){let mut owner=semio_framework_value::retirement::controlled::ControlledRetirement::retain(value);for _ in 0..10000{if owner.terminal_is_empty(){return}let d=owner.selected_demand(4096).unwrap();let g=RetainedCloneGrant{maximum_copy_bytes:4096,..grant(d)};self.caller.turn_with_decoder(g,&mut self.decoder,|cx|{semio_framework_job::close_original_retained_step(cx,d,|loan|{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(loan));let p=result.as_ref().map(|step|step.progress()).unwrap_or_else(|error|error.retained_progress());assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));semio_framework_value::RetainedWorkOutcome{result,work:owner.last_turn_work()}})?;Ok(())}).unwrap();}panic!("original semantic output did not close")}
 fn finish(mut self){for _ in 0..10000{if self.decoder.terminal_is_empty(){self.caller.retire(Self::stock());return}let d=self.decoder.retirement_demands(4096).unwrap();let g=RetainedCloneGrant{maximum_copy_bytes:4096,..grant(d)};self.caller.turn(g,|cx|{semio_framework_job::close_original_retained_step(cx,d,|loan|self.decoder.close_step(loan))?;Ok(())}).unwrap();}panic!("original semantic decoder did not close")}
}
#[test]
fn original_semantic_factory_matches_neutral_outputs_and_exact_physical_turns(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../🌱️derived/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for case in law["cases"].as_array().unwrap().iter(){for cancel_at in [None,Some(0),Some(1),Some(2),Some(8),Some(16)]{
  let snapshots:Arc<dyn ArtifactOwnedValueRetirementFactory<u64>>=Arc::new(semio_framework_value_factory::OwnedValueRetirementFactory::<u64>::default());let mutations:Arc<dyn ArtifactOwnedValueRetirementFactory<u64>>=Arc::new(semio_framework_value_factory::OwnedValueRetirementFactory::<u64>::default());
  let factory=RetainedClonePreparationFactory::new(Arc::new(ScalarEdit),Arc::clone(&mutations),Arc::new(semio_framework_value_factory::SharedValueRetirementFactory::<u64>::default()),64).unwrap();
  let before=case["base"]["n"].as_u64().unwrap();let after=case["after"]["n"].as_u64().unwrap();let accepted=case["accepted"].as_bool().unwrap();let mut original=Some(if accepted{after}else{0});let(mut source,_)=ArtifactMutationSource::admit(&mut original,&mutations,grant(ArtifactMutationSource::<u64>::constructor_demand())).unwrap().unwrap();
  let mut input=None;for _ in 0..8{if source.ready(){source.take(&mut input,grant(source.demands(4096).unwrap())).unwrap();break;}let d=source.demands(4096).unwrap();let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||source.advance(grant(d)).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
  let address=input.as_ref().unwrap().borrow().unwrap().get()as*const u64;
  let registry=SnapshotReadRegistryHandle::new();let root=Arc::new(before);let lease=registry.try_issue(Arc::clone(&root)).unwrap_or_else(|_|panic!("original read registry"));let context=ArtifactReplayPreparationContext{mode:super::super::ArtifactReplayPreparationMode::Prefix,operation_index:0,generation:7,base_revision:[9;32]};
  let request=ArtifactReplayPreparationRequest{base:SnapshotRead::new(Arc::clone(&root),lease),input:input.take().unwrap(),context,snapshots:Arc::clone(&snapshots),mutations:Arc::clone(&mutations)};
  let mut original_caller=OriginalLawCaller::new();let g=grant(factory.preparation_birth_demand());let(mut cursor,p)=original_caller.native(g,|control|{assert!(control.prepare_work(1).unwrap());control.admit_turn_capacity(g.maximum_capacity_bytes).unwrap();control.charge(g.maximum_capacity_bytes).unwrap();let(cursor,p)=ArtifactReplayPreparationFactory::begin(&factory,request,g).map_err(|(error,_)|error).unwrap();control.commit_work(1).unwrap();((cursor,p),p,1)});assert!(p.fits(g));
  let mut ready=false;for turn in 0..10000{if cancel_at==Some(turn){cursor.cancel();break;}let d=cursor.advance_demands(4096).unwrap();let g=grant(d);
   for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}let blocked=original_caller.native(g,|control|{let step=cursor.advance(4096,ArtifactStoreOneItemGrant{maximum_items:denied.maximum_items,maximum_copy_bytes:denied.maximum_copy_bytes,maximum_capacity_bytes:denied.maximum_capacity_bytes,maximum_release_bytes:denied.maximum_release_bytes,maximum_depth:denied.maximum_depth},control).unwrap();(step,step.progress(),cursor.last_turn_work())});assert_eq!(blocked,ArtifactReplayPreparationStep::Blocked);}
   let step=original_caller.native(g,|control|{let step=cursor.advance(4096,ArtifactStoreOneItemGrant{maximum_items:g.maximum_items,maximum_copy_bytes:g.maximum_copy_bytes,maximum_capacity_bytes:g.maximum_capacity_bytes,maximum_release_bytes:g.maximum_release_bytes,maximum_depth:g.maximum_depth},control).unwrap();(step,step.progress(),cursor.last_turn_work())});if matches!(step,ArtifactReplayPreparationStep::Prepared(_)){ready=true;break;}
  }
  if cancel_at.is_none(){assert!(ready);let mut result=cursor.take_prepared().unwrap();if accepted{assert_eq!(**result.next.as_ref().unwrap(),after);assert_eq!(result.inverse.as_ref().unwrap().first(),Some(&before));original_caller.close(result.next.take().unwrap());}else{assert!(result.next.is_none());assert!(result.inverse.as_ref().unwrap().is_empty());assert_eq!(result.messages.len(),1);assert_eq!(result.messages[0].code.0,"mutation.invariant");assert_eq!(result.messages[0].message,"scalar source must be positive");assert_eq!(result.messages[0].level,semio_framework_diagnostic::Severity::Fatal);}original_caller.close(result.inverse.unwrap());original_caller.close(result.messages);}
  cursor.cancel();cursor.begin_close();for _ in 0..10000{if cursor.terminal_is_empty(){break;}let g=grant(cursor.close_demands(4096).unwrap());original_caller.native(g,|control|{let step=control.with_retirement(g,|receiving|cursor.close_step(g,receiving)).unwrap();((),step.progress(),cursor.last_turn_work())});}assert!(cursor.terminal_is_empty());let released=std::mem::size_of_val(cursor.as_ref());let d=RetirementDemand{release_bytes:released,depth:1,..Default::default()};original_caller.native(grant(d),|control|{assert!(control.prepare_work(1).unwrap());drop(cursor);control.commit_work(1).unwrap();((),RetainedCloneProgress{copied_items:1,released_bytes:released,..Default::default()},1)});let mut active:Option<Box<dyn ErasedSnapshotRetirement>>=None;for _ in 0..10000{if !registry.has_returned()&&active.is_none(){break;}let d=if let Some(active)=active.as_ref(){semio_framework_value_snapshot_read::artifact_retirement_box_demands(active,4096).unwrap()}else{registry.returned_admission_demands::<u64>(|_|RetirementDemand{capacity_bytes:semio_framework_value::factory::FactorySharedRetirement::<u64>::constructor_capacity_bytes(),depth:1,..Default::default()}).unwrap()};let g=grant(d);semio_framework_value_snapshot_read::advance_returned_snapshot_read(&registry,&mut active,&snapshots,g).result.unwrap();}assert!(!registry.has_returned()&&active.is_none());
  source.begin_close();for _ in 0..10000{if source.terminal_is_empty(){break;}let g=grant(source.close_demand(4096).unwrap());let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||source.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(source.terminal_is_empty());assert!(!address.is_null());original_caller.close(root);original_caller.finish();
 }
 }
}

